{
  "titles": [
    {
      "id": "c1",
      "text": "양재2동 상가 밀집 지역에서 시작하는 산책"
    },
    {
      "id": "c2",
      "text": "마방 근린공원 인근 상가 길에서 냄새 맡는 보리"
    },
    {
      "id": "c3",
      "text": "바우뫼 근린공원 근처 숲길 산책"
    },
    {
      "id": "c4",
      "text": "종열 어린이공원 인근 풀밭에서 휴식과 반환점"
    },
    {
      "id": "c5",
      "text": "종열 어린이공원 주변을 지나며 되돌아가는 길"
    },
    {
      "id": "c6",
      "text": "바우뫼 근린공원 인근 상가 구간 통과"
    },
    {
      "id": "c7",
      "text": "마방 근린공원 근처 풀밭을 지나며 남기는 기록"
    },
    {
      "id": "c8",
      "text": "마방 근린공원 인근 상가 구간을 끝으로 산책 종료"
    }
  ]
}
